[CmdletBinding(SupportsShouldProcess=$true,ConfirmImpact='High')]
param([ValidateSet('Check','Capture','DryRun','Apply','Verify','VerifyReboot','Rollback')][string]$Action='Check',[string]$StatePath=(Join-Path $PSScriptRoot 'state.json'),[string]$LogPath=(Join-Path $PSScriptRoot 'events.jsonl'))
Set-StrictMode -Version Latest;$ErrorActionPreference='Stop'
$script:RunPath='HKCU:\Software\Microsoft\Windows\CurrentVersion\Run'
$script:ProtectedTokens=@('omnissa','vmware horizon','windows app','remote desktop','mstsc','tailscale','windows security','securityhealth','defender','credential','bitlocker','firewall')
function Write-ExpLog{param([string]$Event,[string]$Result,[hashtable]$Data=@{});$r=[ordered]@{timestampUtc=(Get-Date).ToUniversalTime().ToString('o');experiment='EXP-045';action=$Action;event=$Event;result=$Result;data=$Data};Add-Content -LiteralPath $LogPath -Value ($r|ConvertTo-Json -Compress -Depth 8) -Encoding UTF8}
function Get-SupportState{$os=Get-CimInstance Win32_OperatingSystem;$c=Get-CimInstance Win32_ComputerSystem;[pscustomobject]@{Supported=([version]$os.Version).Major-ge 10 -and $os.Caption-match'Windows 11' -and $c.Manufacturer-match'HP|Hewlett-Packard';OS=$os.Caption;Build=$os.BuildNumber;Manufacturer=$c.Manufacturer;Model=$c.Model}}
function Test-ProtectedIdentity([string]$Name,[string]$Command){$i=($Name+' '+$Command).ToLowerInvariant();foreach($t in $script:ProtectedTokens){if($i.Contains($t)){return $true}};$false}
function Test-OneDriveIdentity([string]$Name,[string]$Command){if(Test-ProtectedIdentity $Name $Command){return $false};$nameMatch=$Name-match'(?i)^(OneDrive|Microsoft OneDrive)$';$exeMatch=$Command-match'(?i)(^|[\\/" ])OneDrive\.exe(?:[" ]|$)';$background=$Command-match'(?i)(^|\s)/background(?:\s|$)';$refused=$Command-match'(?i)OneDriveSetup|OneDriveStandaloneUpdater|update\.exe|/update|/install';return($nameMatch-and$exeMatch-and$background-and-not$refused)}
function Get-Candidates{if(-not(Test-Path $script:RunPath)){return @()};$k=Get-Item -LiteralPath $script:RunPath;$a=foreach($n in $k.GetValueNames()){$v=[string]$k.GetValue($n,$null,[Microsoft.Win32.RegistryValueOptions]::DoNotExpandEnvironmentNames);if(Test-OneDriveIdentity $n $v){[pscustomobject]@{Path=$script:RunPath;Name=$n;Data=$v;Kind=$k.GetValueKind($n).ToString()}}};@($a)}
function Save-State([object[]]$Candidates){if($Candidates.Count-gt 1){throw'More than one eligible OneDrive Run registration was found.'};$s=[ordered]@{schemaVersion=1;experiment='EXP-045';capturedUtc=(Get-Date).ToUniversalTime().ToString('o');machine=$env:COMPUTERNAME;userSid=([System.Security.Principal.WindowsIdentity]::GetCurrent().User.Value);entries=@($Candidates)};$s|ConvertTo-Json -Depth 8|Set-Content -LiteralPath $StatePath -Encoding UTF8;$s}
function Read-State{if(-not(Test-Path $StatePath)){throw"State file missing: $StatePath"};$s=Get-Content -LiteralPath $StatePath -Raw|ConvertFrom-Json;$sid=[System.Security.Principal.WindowsIdentity]::GetCurrent().User.Value;if($s.schemaVersion-ne 1-or$s.experiment-ne'EXP-045'-or$s.machine-ne$env:COMPUTERNAME-or$s.userSid-ne$sid){throw'State identity validation failed.'};$s}
function Remove-Candidates([object[]]$Candidates){foreach($e in $Candidates){if(-not(Test-OneDriveIdentity $e.Name $e.Data)){throw"Candidate identity changed: $($e.Name)"};if($PSCmdlet.ShouldProcess("$($e.Path)::$($e.Name)",'Remove OneDrive background startup registration')){Remove-ItemProperty -LiteralPath $e.Path -Name $e.Name -ErrorAction SilentlyContinue}}}
function Restore-State($State){foreach($e in @($State.entries)){if(-not(Test-OneDriveIdentity $e.Name $e.Data)){throw"Rollback state identity rejected: $($e.Name)"};if(Get-ItemProperty -LiteralPath $e.Path -Name $e.Name -ErrorAction SilentlyContinue){throw"Rollback refused because the registration already exists: $($e.Name)"};if($PSCmdlet.ShouldProcess("$($e.Path)::$($e.Name)",'Restore OneDrive background startup registration')){if(-not(Test-Path $e.Path)){New-Item -Path $e.Path -Force|Out-Null};(Get-Item -LiteralPath $e.Path).SetValue($e.Name,[string]$e.Data,[Microsoft.Win32.RegistryValueKind]::$($e.Kind))}}}
function Test-Removed($State){foreach($e in @($State.entries)){if(Get-ItemProperty -LiteralPath $e.Path -Name $e.Name -ErrorAction SilentlyContinue){return $false}};$true}
function Test-Restored($State){foreach($e in @($State.entries)){$k=Get-Item -LiteralPath $e.Path -ErrorAction SilentlyContinue;if(-not$k){return $false};$v=[string]$k.GetValue($e.Name,$null,[Microsoft.Win32.RegistryValueOptions]::DoNotExpandEnvironmentNames);if($v-ne[string]$e.Data-or$k.GetValueKind($e.Name).ToString()-ne[string]$e.Kind){return $false}};$true}
try{$support=Get-SupportState;Write-ExpLog 'support-detection' $(if($support.Supported){'pass'}else{'unsupported'}) @{os=$support.OS;build=$support.Build;manufacturer=$support.Manufacturer;model=$support.Model};if(-not$support.Supported){throw'EXP-045 supports HP systems running Windows 11 only.'};switch($Action){'Check'{$c=Get-Candidates;Write-ExpLog 'candidate-inventory' 'pass' @{count=$c.Count;names=@($c.Name)};$c}'Capture'{$c=Get-Candidates;$s=Save-State $c;Write-ExpLog 'state-capture' 'pass' @{count=$c.Count;statePath=$StatePath};$s}'DryRun'{$c=Get-Candidates;if($c.Count-gt 1){throw'Dry run found multiple eligible registrations.'};Write-ExpLog 'dry-run' 'pass' @{count=$c.Count;names=@($c.Name)};[pscustomobject]@{WouldRemove=@($c);StatePath=$StatePath}}'Apply'{$c=Get-Candidates;if(-not(Test-Path $StatePath)){Save-State $c|Out-Null}else{$saved=Read-State;foreach($x in $c){if(@($saved.entries|Where-Object{$_.Name-eq$x.Name-and$_.Data-eq$x.Data-and$_.Kind-eq$x.Kind}).Count-ne 1){throw"Current candidate differs from captured state: $($x.Name)"}}};Remove-Candidates $c;$s=Read-State;if(-not(Test-Removed $s)){throw'Apply verification failed.'};Write-ExpLog 'apply' 'pass' @{removed=$c.Count};[pscustomobject]@{Applied=$true;Removed=$c.Count}}'Verify'{$s=Read-State;$ok=Test-Removed $s;Write-ExpLog 'verify' $(if($ok){'pass'}else{'fail'}) @{};if(-not$ok){throw'Removal verification failed.'};$true}'VerifyReboot'{$s=Read-State;$ok=Test-Removed $s;Write-ExpLog 'verify-reboot' $(if($ok){'pass'}else{'fail'}) @{bootTime=(Get-CimInstance Win32_OperatingSystem).LastBootUpTime};if(-not$ok){throw'Reboot persistence verification failed.'};$true}'Rollback'{$s=Read-State;Restore-State $s;if(-not(Test-Restored $s)){throw'Rollback verification failed.'};Write-ExpLog 'rollback' 'pass' @{restored=@($s.entries).Count};[pscustomobject]@{RolledBack=$true;Restored=@($s.entries).Count}}}}catch{Write-ExpLog 'failure' 'fail' @{message=$_.Exception.Message;type=$_.Exception.GetType().FullName};throw}
